INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 8, 'theory', 'Quiz: sorting and list comprehensions');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 8, 0, 'nums = [3, 1, 2]; sorted(nums). What is the list nums after that?', '["[1, 2, 3]", "[3, 2, 1]", "[3, 1, 2]", "None"]', 2, 'sorted returns a new list and leaves the original untouched, unlike the sort method.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 8, 1, 'What will nums hold after the line nums = nums.sort()?', '["A sorted list", "None", "An empty list", "An error at startup"]', 1, 'sort changes the list in place and returns None, so the assignment overwrites the list with nothing.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 8, 2, 'What does the key parameter do in sorted(words, key=len)?', '["Sorts by the length of the list words", "Keeps only the words of length len", "Sorts by the value that len computed for each element", "Sorts alphabetically"]', 2, 'key is a function that Python applies to each element; the order is built from its results.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 8, 3, 'What will [x for x in [1, 2, 3, 4] if x > 2] return?', '["[1, 2]", "[3, 4]", "[False, False, True, True]", "[1, 2, 3, 4]"]', 1, 'The condition at the end of the comprehension selects elements: only 3 and 4 make it into the result.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 8, 4, 'What will any([]) and all([]) return for an empty list?', '["False and True", "True and True", "False and False", "True and False"]', 0, 'There are no fitting elements, so any gives False; there are no violators either, so all gives True.');
